{"content":"@echo off
title v2rayN — Auto Fix Russia Preset
echo ========================================
echo   v2rayN — Auto Fix Russia Preset
echo ========================================
echo.

:: Kill v2rayN if running
taskkill /f /im v2rayN.exe 2>nul
if %errorlevel% equ 0 (
    echo [OK] v2rayN stopped
) else (
    echo [..] v2rayN was not running
)

:: Wait for process to release files
timeout /t 2 /nobreak >nul

:: Backup current config
set CONFIG_DIR=%~dp0guiConfigs
set NOW=%DATE:~-4%%DATE:~3,2%%DATE:~0,2%_%TIME:~0,2%%TIME:~3,2%%TIME:~6,2%
set NOW=%NOW: =0%

copy "%CONFIG_DIR%\guiNConfig.json" "%CONFIG_DIR%\guiNConfig.json.backup-%NOW%" >nul 2>&1
echo [OK] Current config backed up

:: Restore autofix preset (has Russia rules)
if exist "%CONFIG_DIR%\guiNConfig.json.autofix-backup" (
    copy /Y "%CONFIG_DIR%\guiNConfig.json.autofix-backup" "%CONFIG_DIR%\guiNConfig.json" >nul
    echo [OK] Russia preset applied from autofix-backup
) else (
    echo [WARN] autofix-backup not found — Russia preset may need manual setup
    echo [..] See README-FIX.md for instructions
)

:: Verify the config has Russia routing settings
findstr /C:"runetfreedom" "%CONFIG_DIR%\guiNConfig.json" >nul 2>&1
if %errorlevel% equ 0 (
    echo [OK] Russia routing rules confirmed in config
) else (
    echo [WARN] Russia routing rules not found — check README-FIX.md
)

echo.
echo ========================================
echo   Done. Russia preset applied.
echo   Start v2rayN manually or reboot.
echo ========================================
pause
","path":"D:\v2rayN-windows-64\auto-fix-russia-preset.bat"}

